CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY, token_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now() + interval '2 days');
CREATE TABLE IF NOT EXISTS people (workspace uuid REFERENCES workspaces ON DELETE CASCADE, id text, role text NOT NULL CHECK(role IN ('parent','accounts')), name text NOT NULL, centres text[] NOT NULL DEFAULT '{}', password_hash text, consent boolean NOT NULL DEFAULT false, locale text NOT NULL DEFAULT 'en' CHECK(locale IN ('en','hi')), PRIMARY KEY(workspace,id));
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, workspace uuid NOT NULL, person_id text NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(workspace,person_id) REFERENCES people ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS otp_challenges (id uuid PRIMARY KEY, workspace uuid NOT NULL, person_id text NOT NULL, code_hash text NOT NULL, attempts int NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, consumed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace,person_id) REFERENCES people ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS students (workspace uuid REFERENCES workspaces ON DELETE CASCADE, id text, name text NOT NULL, centre text NOT NULL, batch text NOT NULL, parent_id text NOT NULL, plan jsonb NOT NULL, revision int NOT NULL DEFAULT 0, PRIMARY KEY(workspace,id), FOREIGN KEY(workspace,parent_id) REFERENCES people(workspace,id));
CREATE INDEX IF NOT EXISTS students_scope ON students(workspace,centre,batch,parent_id);
CREATE TABLE IF NOT EXISTS ledger_events (workspace uuid, id text, student_id text NOT NULL, data jsonb NOT NULL, PRIMARY KEY(workspace,id), FOREIGN KEY(workspace,student_id) REFERENCES students ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS ledger_student ON ledger_events(workspace,student_id);
CREATE TABLE IF NOT EXISTS receipts (workspace uuid, id text, student_id text NOT NULL, amount bigint NOT NULL CHECK(amount>0), at timestamptz NOT NULL, reference text NOT NULL, PRIMARY KEY(workspace,id), UNIQUE(workspace,reference), FOREIGN KEY(workspace,student_id) REFERENCES students ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS checkouts (workspace uuid, id uuid, student_id text NOT NULL, instalment_id text NOT NULL, amount bigint NOT NULL CHECK(amount>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','success','failure')), expires_at timestamptz NOT NULL DEFAULT now()+interval '20 minutes', PRIMARY KEY(workspace,id), FOREIGN KEY(workspace,student_id) REFERENCES students ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reminders (workspace uuid, id text, student_id text NOT NULL, instalment_id text NOT NULL, scheduled date NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','cancelled','skipped')), locale text NOT NULL DEFAULT 'en', body text, sent_at timestamptz, PRIMARY KEY(workspace,id), FOREIGN KEY(workspace,student_id) REFERENCES students ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS reminder_due ON reminders(scheduled,status);
CREATE TABLE IF NOT EXISTS attendance (workspace uuid, student_id text, day date, present boolean NOT NULL, PRIMARY KEY(workspace,student_id,day), FOREIGN KEY(workspace,student_id) REFERENCES students ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS test_results (workspace uuid, student_id text, name text, day date, marks numeric NOT NULL CHECK(marks>=0), maximum numeric NOT NULL CHECK(maximum>0 AND marks<=maximum), PRIMARY KEY(workspace,student_id,name,day), FOREIGN KEY(workspace,student_id) REFERENCES students ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS risk_assessments (workspace uuid, student_id text, evidence_hash text, data jsonb NOT NULL, PRIMARY KEY(workspace,student_id,evidence_hash), FOREIGN KEY(workspace,student_id) REFERENCES students ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS call_tasks (workspace uuid, student_id text, evidence_hash text, dismissed boolean NOT NULL DEFAULT false, PRIMARY KEY(workspace,student_id,evidence_hash), FOREIGN KEY(workspace,student_id,evidence_hash) REFERENCES risk_assessments ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ai_attempts (id uuid PRIMARY KEY, workspace uuid REFERENCES workspaces ON DELETE CASCADE, day date NOT NULL, at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'reserved');
CREATE INDEX IF NOT EXISTS ai_day ON ai_attempts(day,workspace);
CREATE TABLE IF NOT EXISTS import_previews (id uuid PRIMARY KEY, workspace uuid REFERENCES workspaces ON DELETE CASCADE, person_id text NOT NULL, batch text NOT NULL, kind text NOT NULL, rows jsonb NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '30 minutes', confirmed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS consent_events (id uuid PRIMARY KEY, workspace uuid REFERENCES workspaces ON DELETE CASCADE, person_id text NOT NULL, granted boolean NOT NULL, at timestamptz NOT NULL DEFAULT now(), policy_version text NOT NULL DEFAULT 'demo-v1');
CREATE TABLE IF NOT EXISTS auth_attempts (workspace uuid REFERENCES workspaces ON DELETE CASCADE, at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS auth_attempts_recent ON auth_attempts(workspace,at);
CREATE OR REPLACE FUNCTION preserve_financial_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='UPDATE' OR pg_trigger_depth()=1 THEN RAISE EXCEPTION 'Posted financial history is immutable; record a reversal'; END IF; RETURN OLD; END $$;
DROP TRIGGER IF EXISTS immutable_ledger ON ledger_events;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON ledger_events FOR EACH ROW EXECUTE FUNCTION preserve_financial_history();
DROP TRIGGER IF EXISTS immutable_receipts ON receipts;
CREATE TRIGGER immutable_receipts BEFORE UPDATE OR DELETE ON receipts FOR EACH ROW EXECUTE FUNCTION preserve_financial_history();
